 <el-empty v-if="!rows.length" :description="data.skus.length||data.spus.length?'没有符合当前筛选的二手商品':'暂无二手商品，新增商品后会自动生成 SPU 与 SKU 记录。'"><el-button v-if="can('create')" type="primary" @click="openSku()">新增二手商品</el-button></el-empty>
 <el-table v-else-if="mode==='spu'" :data="pageRows" row-key="id" data-used-spus><el-table-column label="商品主体" min-width="210"><template #default="{row}"><el-button link type="primary" :data-used-spu="row.id" @click="openSpu(row,true)">{{row.name}}</el-button><small>{{row.code}} · {{row.brand||'未填品牌'}} · {{row.model||'未填型号'}}</small></template></el-table-column><el-table-column prop="skuCount" label="单机总数" width="100"/><el-table-column prop="onSaleCount" label="可售数量" width="100"/><el-table-column label="在售价格区间" min-width="160"><template #default="{row}">{{row.minPrice===null?'未填写':row.minPrice===row.maxPrice?money(row.minPrice):money(row.minPrice)+' ～ '+money(row.maxPrice)}}</template></el-table-column><el-table-column label="更新时间" min-width="150"><template #default="{row}">{{time(row.updatedAt)}}</template></el-table-column><el-table-column label="操作" width="245"><template #default="{row}"><div class="actions"><el-button text type="primary" :data-used-drill="row.id" @click="drill(row.id)">查看SKU</el-button><el-button v-if="can('update')" text @click="openSpu(row)">编辑</el-button><el-button v-if="can('create')" text @click="openFromSpu(row)">新增单机</el-button><el-button v-if="can('delete')" text type="danger" @click="removeSpu(row)">删除</el-button></div></template></el-table-column></el-table>
 <el-table v-else :data="pageRows" row-key="id" data-used-skus><el-table-column label="单机商品" min-width="245"><template #default="{row}"><div class="product"><el-image v-if="row.image" :src="row.image" fit="contain" lazy><template #error><el-icon><Goods/></el-icon></template></el-image><el-icon v-else class="placeholder"><Goods/></el-icon><div><el-button link type="primary" :data-used-sku="row.id" @click="openSku(row,undefined,true)">{{row.name}}</el-button><small>{{row.code}}</small><small>{{row.spec||'未填规格'}} · {{row.color||'未填颜色'}}</small></div></div></template></el-table-column><el-table-column label="分组" min-width="100"><template #default="{row}">{{groupName(row.groupId)}}</template></el-table-column><el-table-column label="采购成本" min-width="110"><template #default="{row}">{{money(row.costCents)}}</template></el-table-column><el-table-column label="销售价格" min-width="110"><template #default="{row}">{{money(row.priceCents)}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='on_sale'?'success':row.status==='sold'?'info':'warning'" size="small">{{usedStatusLabel[row.status as UsedStatus]}}</el-tag></template></el-table-column><el-table-column label="操作" width="300"><template #default="{row}"><div class="actions"><el-button v-if="can('update')&&!terminal(row)" text :data-edit-used="row.id" @click="openSku(row)">编辑</el-button><el-button v-if="can('create')" text :data-copy-used="row.id" @click="openSku(undefined,row)">复制新增</el-button><template v-if="can('publish')&&!terminal(row)"><el-button v-if="row.status==='pending'" text type="primary" :data-list-used="row.id" @click="changeStatus(row,'on_sale')">上架</el-button><el-button v-else text type="primary" :data-sell-used="row.id" @click="changeStatus(row,'sold')">标记已售</el-button><el-dropdown trigger="click"><el-button text>更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="row.status==='on_sale'" @click="changeStatus(row,'pending')">下架</el-dropdown-item><el-dropdown-item @click="changeStatus(row,'archived')">归档</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template><el-button v-if="can('delete')" text type="danger" :data-delete-used="row.id" @click="removeSku(row)">删除</el-button></div></template></el-table-column></el-table>
 <el-pagination v-if="rows.length" :current-page="page" :page-size="size" :page-sizes="[20,50]" :total="rows.length" layout="total, sizes, prev, pager, next" @current-change="patch({usedPage:String($event)})" @size-change="patch({usedSize:String($event),usedPage:undefined})"/>
 </section>
 <el-dialog v-model="skuOpen" class="used-sku-dialog" align-center :title="readOnly?'二手单机详情':editing?'编辑二手商品':'新增二手商品'" width="min(640px,96vw)" :close-on-click-modal="false" :before-close="closeSku" destroy-on-close append-to-body><UsedSkuForm v-if="skuOpen" :key="formKey" ref="skuForm" :data="data" :record="editing" :seed="seed" :readonly="readOnly" @close="closeSku(()=>skuOpen=false)" @saved="saved"/></el-dialog>
 <el-dialog v-model="groupsOpen" title="二手自定义分组" width="min(650px,96vw)" :close-on-click-modal="false" :before-close="closeGroups"><p class="muted">分组仅用于管理，可不分组，不影响商品主体和模型。</p><div v-if="can(groupEdit?'update':'create')" class="group-editor"><el-input v-model="groupDraft" maxlength="50" placeholder="自定义分组名称" aria-label="二手分组名称"/><el-button type="primary" :disabled="busy||!groupDraft.trim()" data-save-used-group @click="saveGroup">{{groupEdit?'保存修改':'新增分组'}}</el-button><el-button v-if="groupEdit" :disabled="busy" @click="cancelGroupEdit">取消编辑</el-button></div><el-table :data="data.groups"><el-table-column prop="name" label="分组名称"/><el-table-column label="设备数" width="85"><template #default="{row}">{{data.skus.filter(s=>s.groupId===row.id).length}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button v-if="can('update')" text @click="editGroup(row)">编辑</el-button><el-button v-if="can('delete')" text type="danger" :data-remove-used-group="row.id" @click="removeGroup(row)">删除</el-button></template></el-table-column></el-table><el-alert v-if="groupError" :title="groupError" type="error" :closable="false" data-used-group-error/></el-dialog>
 <el-dialog v-model="spuOpen" :title="spuReadOnly?'二手SPU详情':'编辑二手SPU'" width="min(600px,95vw)" :before-close="closeSpu" :close-on-click-modal="false"><el-form v-if="spuDraft" label-position="top" :disabled="busy||spuReadOnly"><el-form-item label="商品主体名称"><el-input v-model="spuDraft.name" aria-label="二手SPU名称" maxlength="120"/></el-form-item><el-form-item label="品牌"><el-input v-model="spuDraft.brand" :disabled="data.skus.some(s=>s.spuId===spuDraft!.id)"/></el-form-item><el-form-item label="型号"><el-input v-model="spuDraft.model" :disabled="data.skus.some(s=>s.spuId===spuDraft!.id)"/></el-form-item></el-form><p class="muted">{{spuDraft?.code}} · {{data.skus.filter(s=>s.spuId===spuDraft?.id).length}} 台单机。已有单机时不批量改写品牌、型号。</p><el-alert v-if="spuError" :title="spuError" type="error" :closable="false"/><template #footer><el-button :disabled="busy" @click="closeSpu(()=>spuOpen=false)">关闭</el-button><el-button v-if="spuReadOnly" type="primary" @click="drill(spuDraft!.id);spuOpen=false">查看所属SKU</el-button><el-button v-else type="primary" :disabled="busy||!spuDraft?.name.trim()" @click="saveSpu">保存主体</el-button></template></el-dialog>
 </div>
</template>
<script setup lang="ts">
import {computed,ref,watch,nextTick,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate,type LocationQueryRaw} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Goods} from '@element-plus/icons-vue'
import PageHead from '../PageHead.vue'
import GoodsModeSwitch from './GoodsModeSwitch.vue'
import UsedSkuForm from './UsedSkuForm.vue'
import {useCatalogStore} from '../../stores/catalog'
import {emptyUsed,emptyUsedInput,usedStatusLabel,normalized,usedSpuRows,parseUsedPrice,type UsedSku,type UsedSpu,type UsedGroup,type UsedInput,type UsedStatus} from '../../domain/usedGoods'
const props=defineProps<{mode:'spu'|'sku'}>(),store=useCatalogStore(),route=useRoute(),router=useRouter(),data=computed(()=>store.data.usedGoods||emptyUsed()),busy=ref(false),error=ref(''),skuOpen=ref(false),editing=ref<UsedSku>(),seed=ref<UsedInput>(),readOnly=ref(false),formKey=ref(0),skuForm=ref<InstanceType<typeof UsedSkuForm>>()
const groupsOpen=ref(false),groupDraft=ref(''),groupInitial=ref(''),groupEdit=ref<UsedGroup>(),groupError=ref(''),spuOpen=ref(false),spuDraft=ref<UsedSpu>(),spuInitial=ref(''),spuReadOnly=ref(false),spuError=ref('')
const actor=()=>JSON.stringify([store.activeUserId,store.previewUserId]),can=(action:string)=>store.can('product:used-goods:'+action),copy=<T>(v:T):T=>JSON.parse(JSON.stringify(v)),money=(v:number|null)=>v===null?'未填写':'¥'+(v/100).toFixed(2),time=(v:string)=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Singapore',hour12:false}),terminal=(s:UsedSku)=>!!s.soldAt||s.status==='sold'||s.status==='archived',groupName=(id:string|null)=>data.value.groups.find(g=>g.id===id)?.name||'未分组'
function patch(value:LocationQueryRaw){void router.replace({path:route.path,query:{...route.query,...value}})}
function filter(key:string,fallback=''){return computed({get:()=>String(route.query[key]||fallback),set:(value:string)=>patch({[key]:value||undefined,usedPage:undefined})})}
const keyword=filter('usedQ'),brand=filter('usedBrand'),model=filter('usedModel'),group=filter('usedGroup'),status=filter('usedStatus'),minPrice=filter('usedMin'),maxPrice=filter('usedMax'),sort=filter('usedSort','updated'),scopeSpu=computed(()=>props.mode==='sku'?data.value.spus.find(s=>s.id===route.query.usedSpu):undefined),brands=computed(()=>[...new Set(data.value.spus.map(s=>s.brand).filter(Boolean))]),models=computed(()=>[...new Set(data.value.spus.filter(s=>!brand.value||normalized(s.brand)===normalized(brand.value)).map(s=>s.model).filter(Boolean))])
const priceError=computed(()=>parseUsedPrice(minPrice.value)===undefined||parseUsedPrice(maxPrice.value)===undefined?'价格筛选最多两位小数':minPrice.value&&maxPrice.value&&parseUsedPrice(minPrice.value)!>parseUsedPrice(maxPrice.value)!?'最低价不能高于最高价':'')
const filteredSkus=computed(()=>{const low=parseUsedPrice(minPrice.value),high=parseUsedPrice(maxPrice.value),q=normalized(keyword.value);return priceError.value?[]:data.value.skus.filter(s=>{const p=data.value.spus.find(p=>p.id===s.spuId)!;return (!route.query.usedSpu||props.mode!=='sku'||s.spuId===route.query.usedSpu)&&(!q||normalized([s.code,s.name,s.spec,s.color,s.serial,s.imei,p?.name,p?.brand,p?.model].join(' ')).includes(q))&&(!brand.value||normalized(p?.brand||'')===normalized(brand.value))&&(!model.value||normalized(p?.model||'')===normalized(model.value))&&(!group.value||(group.value==='__none'?s.groupId===null:s.groupId===group.value))&&(!status.value||s.status===status.value)&&(low===null||low===undefined||s.priceCents!==null&&s.priceCents>=low)&&(high===null||high===undefined||s.priceCents!==null&&s.priceCents<=high)})})
const rows=computed(()=>{const list=props.mode==='sku'?filteredSkus.value:usedSpuRows(data.value).filter(p=>{const q=normalized(keyword.value),hasRestrictions=!!(group.value||status.value||minPrice.value||maxPrice.value);return (!q||normalized([p.code,p.name,p.brand,p.model].join(' ')).includes(q)||filteredSkus.value.some(s=>s.spuId===p.id))&&(!brand.value||normalized(p.brand)===normalized(brand.value))&&(!model.value||normalized(p.model)===normalized(model.value))&&(!hasRestrictions||filteredSkus.value.some(s=>s.spuId===p.id))});return [...list].sort((a,b)=>sort.value==='name'?a.name.localeCompare(b.name,'zh-CN'):sort.value==='price'?((('priceCents'in a?a.priceCents:a.minPrice)??Infinity)-(('priceCents'in b?b.priceCents:b.minPrice)??Infinity)||a.code.localeCompare(b.code)):b.updatedAt.localeCompare(a.updatedAt)||a.code.localeCompare(b.code))})
const size=computed(()=>route.query.usedSize==='50'?50:20),page=computed(()=>Math.max(1,Math.min(Math.ceil(rows.value.length/size.value)||1,Math.trunc(Number(route.query.usedPage))||1))),pageRows=computed(()=>rows.value.slice((page.value-1)*size.value,page.value*size.value))
function resetFilters(){const query:LocationQueryRaw={...route.query};for(const k of Object.keys(query))if(k.startsWith('used')&&k!=='usedSpu')delete query[k];void router.replace({path:route.path,query})}
function switchList(){void router.push({path:props.mode==='spu'?'/skus':'/spus',query:{goods:'used'}})}
function drill(id:string){void router.push({path:'/skus',query:{goods:'used',usedSpu:id}})}
function openSku(record?:UsedSku,from?:UsedSku,readonly=false){editing.value=record?copy(record):undefined;seed.value=undefined;readOnly.value=readonly||!!record&&terminal(record);if(from){const p=data.value.spus.find(p=>p.id===from.spuId)!;seed.value={...emptyUsedInput(),spuId:p.id,name:from.name,brand:p.brand,model:p.model,spec:from.spec,color:from.color,groupId:from.groupId}}formKey.value++;skuOpen.value=true;error.value=''}
function openFromSpu(spu:UsedSpu){openSku();seed.value={...emptyUsedInput(),spuId:spu.id,name:spu.name,brand:spu.brand,model:spu.model}}
async function saved(id:string){skuOpen.value=false;await nextTick();ElMessage.success('二手单机已保存');await router.push({path:'/skus',query:{goods:'used',usedFocus:id}})}
const groupDirty=computed(()=>groupsOpen.value&&groupDraft.value!==groupInitial.value),spuDirty=computed(()=>spuOpen.value&&!spuReadOnly.value&&JSON.stringify(spuDraft.value)!==spuInitial.value),dirty=computed(()=>!!skuForm.value?.isDirty||groupDirty.value||spuDirty.value),pending=computed(()=>busy.value||!!skuForm.value?.busy)
async function confirmDiscard(changed:boolean){if(pending.value)return false;if(!changed)return true;try{await ElMessageBox.confirm('当前有未保存的二手资料，确定放弃？','保留或放弃修改',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});return true}catch{return false}}
async function closeSku(done:()=>void){if(await confirmDiscard(!!skuForm.value?.isDirty))done()}
async function closeGroups(done:()=>void){if(await confirmDiscard(groupDirty.value)){groupDraft.value='';groupInitial.value='';groupEdit.value=undefined;groupError.value='';done()}}
async function closeSpu(done:()=>void){if(await confirmDiscard(spuDirty.value))done()}
async function run(action:()=>Promise<{ok:boolean;message?:string}>,localError=error){if(pending.value)return false;busy.value=true;localError.value='';const owner=actor();try{const r=await action();if(owner!==actor())return false;if(!r.ok){localError.value=r.message||'保存失败，输入保留';return false}ElMessage.success(r.message||'操作已保存');return true}catch(e){if(owner===actor())localError.value=String(e);return false}finally{busy.value=false}}
async function changeStatus(row:UsedSku,next:UsedStatus){const owner=actor();try{await ElMessageBox.confirm('将 '+row.code+' 从'+usedStatusLabel[row.status]+'改为'+usedStatusLabel[next]+'？'+(next==='sold'?'已售后保留记录，不能再次销售。':''),'确认设备状态',{confirmButtonText:'确认'+usedStatusLabel[next],cancelButtonText:'取消'});if(owner!==actor())return;await run(()=>store.setUsedSkuStatus(row.id,row.revision,next))}catch{}}
async function removeSku(row:UsedSku){const owner=actor();try{await ElMessageBox.confirm('仅删除尚无业务历史的待上架单机 '+row.code+'；已售及已有状态历史的记录不能删除。','删除二手单机',{confirmButtonText:'确认删除',cancelButtonText:'取消'});if(owner!==actor())return;await run(()=>store.removeUsedSku(row.id,row.revision))}catch{}}
async function removeSpu(row:UsedSpu){const owner=actor();try{await ElMessageBox.confirm('仅删除空的二手SPU，不级联删除任何单机。','删除二手SPU',{confirmButtonText:'确认删除',cancelButtonText:'取消'});if(owner!==actor())return;await run(()=>store.removeUsedSpu(row.id,row.revision))}catch{}}
async function editGroup(row:UsedGroup){if(!await confirmDiscard(groupDirty.value))return;groupEdit.value=copy(row);groupDraft.value=row.name;groupInitial.value=row.name;groupError.value=''}
async function cancelGroupEdit(){if(await confirmDiscard(groupDirty.value)){groupEdit.value=undefined;groupDraft.value='';groupInitial.value=''}}
async function saveGroup(){if(await run(()=>store.saveUsedGroup(groupEdit.value?.id||'',groupDraft.value,groupEdit.value?.revision||0),groupError)){groupDraft.value='';groupInitial.value='';groupEdit.value=undefined}}
async function removeGroup(row:UsedGroup){const owner=actor();try{await ElMessageBox.confirm('删除分组“'+row.name+'”？被设备引用时将拒绝删除，不会删除设备。','删除二手分组',{confirmButtonText:'确认删除',cancelButtonText:'取消'});if(owner!==actor())return;await run(()=>store.removeUsedGroup(row.id,row.revision),groupError)}catch{}}
function openSpu(row:UsedSpu,readonly=false){spuDraft.value=copy(row);spuInitial.value=JSON.stringify(spuDraft.value);spuReadOnly.value=readonly;spuError.value='';spuOpen.value=true}
async function saveSpu(){const row=spuDraft.value;if(!row)return;if(await run(()=>store.saveUsedSpu(row.id,{name:row.name,brand:row.brand,model:row.model},row.revision),spuError)){spuInitial.value=JSON.stringify(spuDraft.value);spuOpen.value=false}}
function unload(e:BeforeUnloadEvent){if(dirty.value||pending.value){e.preventDefault();e.returnValue=''}}window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload));onBeforeRouteLeave(()=>confirmDiscard(dirty.value));onBeforeRouteUpdate((to,from)=>to.query.goods==='used'&&to.path===from.path?true:confirmDiscard(dirty.value))
watch(actor,()=>{skuOpen.value=false;groupsOpen.value=false;spuOpen.value=false;editing.value=undefined;seed.value=undefined;groupDraft.value='';groupInitial.value='';groupEdit.value=undefined;spuDraft.value=undefined;error.value='';groupError.value='';spuError.value=''})
</script>
<style scoped>
:global(.el-overlay-dialog:has(.used-sku-dialog)){display:flex;align-items:center;justify-content:center}
:global(.used-sku-dialog){max-height:calc(100vh - 48px);display:flex;flex-direction:column;overflow:hidden}
:global(.used-sku-dialog .el-dialog__body){overflow:auto;min-height:0}
